import { Project } from '../../src'
import { path, KeysRegistry } from '@servicenow/sdk-build-core'

const DELETE_DIR = 'author_elective_update'
const rootDir = path.resolve(__dirname, 'project')

describe('Delete generation tests', () => {
    test('Create delete from deleted key', async () => {
        const project = new Project({
            rootDir,
            config: {
                generatedDir: 'generated1',
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })
        const output = await project.getOutput()

        expect(output).toHaveLength(4)
        expect(output.find((f) => f.path.endsWith('test_table_12345.xml'))).toMatchObject({
            path: path.join(project.getRootDir(), project.getConfig().appOutputDir, DELETE_DIR, 'test_table_12345.xml'),
            content: `<?xml version="1.0"?>
<record_update table="test_table">
  <test_table action="DELETE">
    <sys_id>12345</sys_id>
    <sys_scope display_value="x_abc">11111111111111111111111111111111</sys_scope>
    <sys_update_name>test_table_12345</sys_update_name>
  </test_table>
</record_update>`,
        })
    })

    test('Create delete from unused explicit key', async () => {
        const project = new Project({
            rootDir,
            config: {
                generatedDir: 'generated2',
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })
        const output = await project.getOutput()

        expect(output).toHaveLength(4)
        expect(output.find((f) => f.path.endsWith('test_table_12345.xml'))).toMatchObject({
            path: path.join(project.getRootDir(), project.getConfig().appOutputDir, DELETE_DIR, 'test_table_12345.xml'),
            content: `<?xml version="1.0"?>
<record_update table="test_table">
  <test_table action="DELETE">
    <sys_id>12345</sys_id>
    <sys_scope display_value="x_abc">11111111111111111111111111111111</sys_scope>
    <sys_update_name>test_table_12345</sys_update_name>
  </test_table>
</record_update>`,
        })
    })

    test('Create delete from unused composite key', async () => {
        const project = new Project({
            rootDir,
            config: {
                generatedDir: 'generated3',
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })
        const output = await project.getOutput()

        expect(output).toHaveLength(5)
        expect(output.find((f) => f.path.endsWith('sys_user_role_12345.xml'))).toMatchObject({
            path: path.join(
                project.getRootDir(),
                project.getConfig().appOutputDir,
                DELETE_DIR,
                'sys_user_role_12345.xml'
            ),
            content: `<?xml version="1.0"?>
<record_update table="sys_user_role">
  <sys_user_role action="DELETE">
    <sys_id>12345</sys_id>
    <sys_scope display_value="x_abc">11111111111111111111111111111111</sys_scope>
    <sys_update_name>sys_user_role_12345</sys_update_name>
    <name>x_abc.name</name>
  </sys_user_role>
</record_update>`,
        })

        expect(output.find((f) => f.path.endsWith('sys_user_role_contains_54321.xml'))).toMatchObject({
            path: path.join(
                project.getRootDir(),
                project.getConfig().appOutputDir,
                DELETE_DIR,
                'sys_user_role_contains_54321.xml'
            ),
            content: `<?xml version="1.0"?>
<record_update table="sys_user_role_contains">
  <sys_user_role_contains action="DELETE">
    <sys_id>54321</sys_id>
    <sys_scope display_value="x_abc">11111111111111111111111111111111</sys_scope>
    <sys_update_name>sys_user_role_contains_54321</sys_update_name>
    <contains name="otherRole">666666</contains>
    <role name="x_abc.name">12345</role>
  </sys_user_role_contains>
</record_update>`,
        })

        const keys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())
        expect(keys.composite.find(({ table, id }) => table === 'sys_user_role' && id === '12345')).toMatchObject({
            deleted: true,
        })
        expect(
            keys.composite.find(({ table, id }) => table === 'sys_user_role_contains' && id === '54321')
        ).toMatchObject({
            deleted: true,
        })
    })

    test('Do not generate delete for admin role', async () => {
        const project = new Project({
            rootDir,
            config: {
                generatedDir: 'generated8',
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        const output = await project.getOutput()

        expect(output).toHaveLength(3)
        expect(output.find((file) => file.path.includes('sys_user_role'))).toBeFalsy()
    })

    test('Do not generate delete for non-scoped role', async () => {
        const project = new Project({
            rootDir,
            config: {
                generatedDir: 'generated9',
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        const output = await project.getOutput()

        expect(output).toHaveLength(3)
        expect(output.find((file) => file.path.includes('sys_user_role'))).toBeFalsy()
    })

    test('Skip delete creation for used explicit ID', async () => {
        const project = new Project({
            rootDir,
            config: {
                generatedDir: 'generated4',
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })
        project.addFile({
            path: 'src/fluent/record.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'
       
        Record({
           $id: Now.ID['12345'],
           table: 'test_table',
           data: {
               name: 'data',
           },
       })
           
       Record({
           $id: '54321',
           table: 'test_table',
           data: {
               name: 'data',
           },
       })`,
        })

        const output = await project.getOutput()

        expect(output).toHaveLength(5)
        expect(output.find((f) => f.path.includes(path.join(DELETE_DIR)))).toBeFalsy()
    })
    test('Skip delete creation for used composite ID', async () => {
        const project = new Project({
            rootDir,
            config: {
                generatedDir: 'generated5',
                scope: 'global',
                scopeId: '11111111111111111111111111111111',
            },
        })

        project.addFile({
            path: 'src/fluent/record.now.ts',
            content: `import { Role } from '@servicenow/sdk/core'
            Role({
                $id: Now.ID['12345'],
                name: 'name',
                contains_roles: [{
                    $id: '54321',
                    name: 'name'
                }]
            })
        `,
        })
        const output = await project.getOutput()

        expect(output).toHaveLength(5)
        expect(output.find((f) => f.path.includes(DELETE_DIR))).toBeFalsy()

        const keys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())

        expect(keys.composite[0].deleted).toBeFalsy()
        expect(keys.composite[1].deleted).toBeFalsy()
        expect(Object.values(keys.deleted)).toHaveLength(0)
    })

    test('Delete creation for unused explicit ID on coalesce table', async () => {
        const project = new Project({
            rootDir,
            config: {
                generatedDir: 'generated6',
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })
        const output = await project.getOutput()
        expect(output).toHaveLength(4)
        expect(output.find((f) => f.path.includes(DELETE_DIR))).toBeTruthy()
        const keys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())
        expect(Object.values(keys.explicit)).toHaveLength(3)
        expect(keys.explicit['myrole'].deleted).toBeTruthy()
        expect(Object.values(keys.deleted)).toHaveLength(0)
    })

    test('V3 coalesce keys are not registered as deletes after upgrade', async () => {
        const project = new Project({
            rootDir,
            config: {
                generatedDir: 'generated7',
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        project.addFile({
            path: `index.now.ts`,
            content: `import { Acl, Role } from '@servicenow/sdk/core'
import { default_view, List } from '@servicenow/sdk/core'
import { RestApi } from '@servicenow/sdk/core'

const approle = Role({
    $id: Now.ID['explicit_role'],
    name: 'x_abc.approle',
    containsRoles: ['otherRole']
})

Acl({
    $id: Now.ID['explicit_acl'],
    active: true,
    admin_overrides: true,
    decision_type: 'allow',
    local_or_existing: 'Local',
    type: 'record',
    table: 'table',
    operation: 'create',
    roles: [approle],
})

RestApi({
    $id: Now.ID['explicit_rest'],
    name: 'name',
    routes: [
        {
            $id: Now.ID['explicit_route'],
            script: 'script',
            parameters: [
                {
                    $id: Now.ID['explicit_query_parameter'],
                    name: 'name',
                },
            ],
        },
    ],
    serviceId: '1235',
})

List({
    $id: Now.ID['explicit_list'],
    view: default_view,
    table: 'table',
    columns: ['active'],
})`,
        })

        const output = await project.getOutput()

        expect(output.find((f) => f.path.includes(DELETE_DIR))).toBeFalsy()
        const keys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())
        expect(Object.values(keys.explicit)).toHaveLength(6) // only keys that allow registering explicit keys remain
        expect(Object.values(keys.explicit).find((val) => val.deleted)).toBeFalsy()
        expect(Object.values(keys.composite).find((val) => val.deleted)).toBeFalsy()
        expect(Object.values(keys.deleted)).toHaveLength(0)
    })
})

describe('Delete transformation tests', () => {
    test('Delete node and file from xml delete action', async () => {
        const project = new Project({
            rootDir,
            config: {
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        project.addFile({
            path: `br.now.ts`,
            content: `import { BusinessRule } from '@servicenow/sdk/core'
            BusinessRule({
                $id: '28dbe31d7fb0ebeb72c32b371a6f554a',
                name: 'Test',
                script: 'gs.info()',
                when: 'async',
                table: 'incident'
            })`,
        })

        const output = await project.transform(['xml/sys_script.xml'])

        expect(output.changedFiles.length).toBe(1)

        expect(project.getFileIfExists('br.now.ts')).toBeTruthy()
    })

    test('Delete node with explicit ID', async () => {
        const project = new Project({
            rootDir,
            config: {
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        project.registerExplicitId('sys_script', 'myID', '28dbe31d7fb0ebeb72c32b371a6f554a')
        project.addFile({
            path: `br.now.ts`,
            content: `import { BusinessRule } from '@servicenow/sdk/core'
            BusinessRule({
                $id: Now.ID['myID'],
                name: 'Test',
                script: 'gs.info()',
                when: 'async',
                table: 'incident'
            })`,
        })

        const output = await project.transform(['xml/sys_script.xml'])

        expect(output.changedFiles.length).toBe(1)
        expect(output.changedFiles[0].getContent()).toBe('')

        expect(project.getFileIfExists('br.now.ts')).toBeTruthy()
    })

    test('Register delete without corresponding node', async () => {
        const project = new Project({
            rootDir,
            config: {
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        const output = await project.transform(['xml/sys_script.xml'])

        expect(output.changedFiles.length).toBe(0)
        expect(project.getFileIfExists('br.now.ts')).toBeFalsy()

        const updatedKeys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())
        expect(Object.entries(updatedKeys.explicit).length).toBe(3)
        expect(
            Object.values(updatedKeys.explicit).find((k) => k.id === '28dbe31d7fb0ebeb72c32b371a6f554a').deleted
        ).toBeTruthy()
        expect(Object.values(updatedKeys.deleted)).toHaveLength(0)
    })

    test('Register coalesce delete without corresponding node', async () => {
        const project = new Project({
            rootDir,
            config: {
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        const output = await project.transform(['xml/sys_user_role.xml'])

        expect(output.changedFiles.length).toBe(0)

        const updatedKeys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())
        expect(updatedKeys.composite).toHaveLength(1)
        expect(updatedKeys.composite[0].deleted).toBeTruthy()
    })

    test('Delete node from xml delete action', async () => {
        const project = new Project({
            rootDir,
            config: {
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        project.addFile({
            path: `br.now.ts`,
            content: `import { BusinessRule } from '@servicenow/sdk/core'
            BusinessRule({
                $id: '28dbe31d7fb0ebeb72c32b371a6f554a',
                name: 'Test',
                script: 'gs.info()',
                when: 'async',
                table: 'incident',
                action: [],
            })
            BusinessRule({
                $id: '28dbe31d7fb0ebeb72c32b371bbbb4bb',
                name: 'Test',
                script: 'gs.info()',
                when: 'async',
                table: 'incident',
                action: [],
            })`,
        })

        const output = await project.transform(['xml/sys_script.xml'])

        expect(output.changedFiles.length).toBe(1)
        expect(project.getFileIfExists('br.now.ts')).toBeTruthy()
        expect(output.changedFiles[0].getContent()).toMatch(`import { BusinessRule } from '@servicenow/sdk/core'
BusinessRule({
    $id: '28dbe31d7fb0ebeb72c32b371bbbb4bb',
    name: 'Test',
    script: 'gs.info()',
    when: 'async',
    table: 'incident',
    action: [],
})
`)

        const updatedKeys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())
        expect(Object.entries(updatedKeys.explicit)).toHaveLength(4)
        expect(
            Object.values(updatedKeys.explicit).find((k) => k.id === '28dbe31d7fb0ebeb72c32b371a6f554a').deleted
        ).toBeTruthy()
    })
    test('Delete node matching coalesce key', async () => {
        const project = new Project({
            rootDir,
            config: {
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        project.addFile({
            path: `role.now.ts`,
            content: `import { Role } from "@servicenow/sdk/core"

Role({
    name: 'x_abc.rolename',
})`,
        })

        const id = project.getKeys().registerCoalesceId('sys_user_role', { name: 'x_abc.rolename' })

        const output = await project.transform(['xml/sys_user_role.xml'])

        expect(output.changedFiles.length).toBe(1)
        expect(project.getFileIfExists('role.now.ts')).toBeTruthy()
        expect(output.changedFiles[0].getContent()).toBe('')

        const updatedKeys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())

        expect(updatedKeys.composite).toHaveLength(1)
        expect(updatedKeys.composite[0]).toMatchObject({
            table: 'sys_user_role',
            id,
            deleted: true,
            key: {
                name: 'x_abc.rolename',
            },
        })
    })

    test('Delete node from referenced location', async () => {
        const project = new Project({
            rootDir,
            config: {
                scope: 'x_abc',
                scopeId: '11111111111111111111111111111111',
            },
        })

        project.addFile({
            path: `acl.now.ts`,
            content: `import { Acl, Role } from '@servicenow/sdk/core'

const manager = Role({
    name: 'x_abc.rolename',
})

Acl({
    $id: Now.ID['read_acl'],
    operation: 'read',
    type: 'record',
    table: 'incident',
    roles: ['admin', manager],
})`,
        })

        const id = project.registerCoalesceId('sys_user_role', { name: 'x_abc.rolename' })
        const output = await project.transform(['xml/sys_user_role.xml'])

        expect(output.changedFiles.length).toBe(1)
        expect(project.getFileIfExists('acl.now.ts')).toBeTruthy()
        expect(output.changedFiles[0].getContent()).toMatch(`import { Acl } from '@servicenow/sdk/core'
Acl({
    $id: Now.ID['read_acl'],
    operation: 'read',
    type: 'record',
    table: 'incident',
    roles: ['admin'],
})`)

        const updatedKeys = KeysRegistry.parseKeysFile(project.getKeys().getSourceFile())

        expect(updatedKeys.composite).toHaveLength(3)
        expect(updatedKeys.composite.find((k) => k.id === id)).toMatchObject({
            table: 'sys_user_role',
            id,
            deleted: true,
            key: {
                name: 'x_abc.rolename',
            },
        })
        expect(Object.entries(updatedKeys.explicit).length).toBe(3) // package.json, bom.json, and acl
        expect(Object.entries(updatedKeys.deleted)).toHaveLength(0)
    })

    test('Deletes in metadata dir should not conflict with themselves', async () => {
        const warnings: string[] = []
        const project = new Project({ logger: { ...console, warn: (msg) => warnings.push(msg) } })
        const xml = `<?xml version="1.0"?>
<record_update>
  <test_table action="DELETE">
    <sys_id>12345</sys_id> <!-- comment -->
  </test_table>
</record_update>`

        project.getKeys().deleteExplicitId('test_table', '1', '12345')
        project.addFile({ path: 'metadata/update/test_record.xml', content: xml })

        const output = await project.getOutput()

        // We always get a sys_app
        expect(output).toContainEqual(
            expect.objectContaining({
                path: expect.stringContaining(`sys_app_${project.getConfig().scopeId}.xml`),
            })
        )

        // And a sys_module for the package.json
        expect(output).toContainEqual(
            expect.objectContaining({
                path: expect.stringContaining(
                    `sys_module_${project.getKeys().queryExplicitId('sys_module', 'package_json')}.xml`
                ),
            })
        )

        // We only expect one delete, and it should be identical to the one in the metadata dir
        expect(output).toContainEqual({
            path: expect.stringContaining('test_record.xml'),
            content: xml,
        })

        expect(output).toHaveLength(4)
        expect(warnings).toHaveLength(0)
    })

    test('Create, then delete, then undelete', async () => {
        const warnings: string[] = []
        const project = new Project({ logger: { ...console, warn: (msg) => warnings.push(msg) } })
        const code = `import { Record, Role } from '@servicenow/sdk/core'
Record({
    $id: Now.ID['abc'],
    table: 'test_table',
    data: {}
})

Role({
    name: 'test'
})`

        project.registerExplicitId('test_table', 'abc', 'abc')
        project.registerCoalesceId('sys_user_role', { name: 'test' }, 'xyz')
        const file = project.addFile({
            path: 'src/fluent/test.now.ts',
            content: code,
        })

        {
            const records = await project.getRecords()
            expect(records.query()).toHaveLength(5)
            expect(warnings).toHaveLength(0)

            const keys = project.getKeys().getValue()
            expect(keys.explicit['abc']).toEqual({ table: 'test_table', id: 'abc' })
            expect(keys.composite[0]).toEqual({ table: 'sys_user_role', id: 'xyz', key: { name: 'test' } })

            const testRecord = records.get('test_table', 'abc')
            expect(testRecord).toBeDefined()
            expect(testRecord.getAction()).toBe('INSERT_OR_UPDATE')

            const roleRecord = records.get('sys_user_role', 'xyz')
            expect(roleRecord).toBeDefined()
            expect(roleRecord.getAction()).toBe('INSERT_OR_UPDATE')
        }

        // Delete the records
        file.setContent('')
        project.getKeys().reload()

        {
            const records = await project.getRecords()
            expect(records.query()).toHaveLength(4)
            expect(warnings).toHaveLength(0)

            const keys = project.getKeys().getValue()
            expect(keys.explicit['abc']).toEqual({ table: 'test_table', id: 'abc', deleted: true })
            expect(keys.composite[0]).toEqual({
                table: 'sys_user_role',
                id: 'xyz',
                deleted: true,
                key: { name: 'test' },
            })

            const testRecord = records.get('test_table', 'abc')
            expect(testRecord).toBeDefined()
            expect(testRecord.getAction()).toBe('DELETE')

            const roleRecord = records.get('sys_user_role', 'xyz')
            expect(roleRecord).toBeUndefined()
        }

        // Bring them back
        file.setContent(code)
        project.getKeys().reload()

        {
            const records = await project.getRecords()
            expect(records.query()).toHaveLength(5)
            expect(warnings).toHaveLength(0)

            const keys = project.getKeys().getValue()
            expect(keys.explicit['abc']).toEqual({ table: 'test_table', id: 'abc', deleted: false })
            expect(keys.composite[0]).toEqual({
                table: 'sys_user_role',
                id: 'xyz',
                deleted: false,
                key: { name: 'test' },
            })

            const testRecord = records.get('test_table', 'abc')
            expect(testRecord).toBeDefined()
            expect(testRecord.getAction()).toBe('INSERT_OR_UPDATE')

            const roleRecord = records.get('sys_user_role', 'xyz')
            expect(roleRecord).toBeDefined()
            expect(roleRecord.getAction()).toBe('INSERT_OR_UPDATE')
        }
    })
})
